mapper.select:
SELECT sku.id AS sku_id, product.product_code, sku.sku_code, product.status AS product_status, sku.status AS sku_status, product.title AS product_title, specification.specification_code, specification.name AS specification_name, specification_value.specification_value_code, specification_value.display_name AS specification_value_name, COALESCE(sku.image_file_id, product.primary_image_file_id) AS image_file_id, sku.price_amount FROM sku INNER JOIN product ON product.id = sku.product_id LEFT JOIN sku_specification_selection selection ON selection.sku_id = sku.id LEFT JOIN product_specification specification ON specification.id = selection.specification_id LEFT JOIN product_specification_value specification_value ON specification_value.id = selection.specification_value_id WHERE sku.sku_code IN
#{skuCode}
ORDER BY sku.sku_code, specification.sort_order
